for line in MATRIX.strip().splitlines():
    fields=line.split("|")
    if len(fields)!=9:raise ValueError(f"Invalid translation row: {fields[0]}")
    for lang,value in zip(ORDER,fields[1:]):CATALOG[lang][fields[0]]=value.replace("\\n","\n")


def detect_language(code):
    code=str(code or "fa").lower().replace("_","-").split("-")[0]
    return "he" if code=="iw" else code if code in LANGUAGES else "en"


def tr(language,key,**values):
    return CATALOG.get(language,CATALOG["en"])[key].format(**values)

